Here is the commit message:
mm/damon/dbgfs: fix memory leak when using debugfs_lookup()

When calling debugfs_lookup() the result must have dput() called on it,
otherwise the memory will leak over time.  Fix this up by properly calling
dput().

Link: https://lkml.kernel.org/r/20220902191149.112434-1-sj@kernel.org
Fixes: 75c1c2b53c78b ("mm/damon/dbgfs: support multiple contexts")
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>
Signed-off-by: SeongJae Park <sj@kernel.org>
Cc: <stable@vger.kernel.org>
Signed-off-by: Andrew Morton <akpm@linux-foundation.org>

Here is the root cause:
The bug is caused by not calling `dput()` on the result of `debugfs_lookup()`, which leads to a memory leak as the reference count for the directory entry is not decremented, causing allocated memory to remain unreleased over time. This oversight occurs during the removal of a context in the `dbgfs_rm_context` function, where the directory entry is not properly managed upon failure or completion of the function.

Here is the patch:
  */
 static int dbgfs_rm_context(char *name)
 {
 	struct dentry *root, *dir, **new_dirs;
 	struct damon_ctx **new_ctxs;
 	int i, j;
+	int ret = 0;

 	if (damon_nr_running_ctxs())
 		return -EBUSY;

 	root = dbgfs_dirs[0];
 	if (!root)
 		return -ENOENT;

 	dir = debugfs_lookup(name, root);
 	if (!dir)
 		return -ENOENT;

 	new_dirs = kmalloc_array(dbgfs_nr_ctxs - 1, sizeof(*dbgfs_dirs),
 			GFP_KERNEL);
-	if (!new_dirs)
-		return -ENOMEM;
+	if (!new_dirs) {
+		ret = -ENOMEM;
+		goto out_dput;
+	}

 	new_ctxs = kmalloc_array(dbgfs_nr_ctxs - 1, sizeof(*dbgfs_ctxs),
 			GFP_KERNEL);
 	if (!new_ctxs) {
-		kfree(new_dirs);
-		return -ENOMEM;
+		ret = -ENOMEM;
+		goto out_new_dirs;
 	}

 	for (i = 0, j = 0; i < dbgfs_nr_ctxs; i++) {
 		if (dbgfs_dirs[i] == dir) {
 			debugfs_remove(dbgfs_dirs[i]);
 			dbgfs_destroy_ctx(dbgfs_ctxs[i]);
 			continue;
 		}
 		new_dirs[j] = dbgfs_dirs[i];
 		new_ctxs[j++] = dbgfs_ctxs[i];
 	}

 	kfree(dbgfs_dirs);
 	kfree(dbgfs_ctxs);

 	dbgfs_dirs = new_dirs;
 	dbgfs_ctxs = new_ctxs;
 	dbgfs_nr_ctxs--;

-	return 0;
+	goto out_dput;
+
+out_new_dirs:
+	kfree(new_dirs);
+out_dput:
+	dput(dir);
+	return ret;
 }



